// KDL 2.0 Schema DSL (v2.1) — HTML Item & List Catalogue
(item)struct QuoteAuthor {
    name { css ".author"; text; trim }
    profile_url { css "a.author-link"; attr "href"; fallback #null }
    tags {
        css-all ".tag"
        filter { has-attr "data-topic" }
        text
        trim
    }
}

(list)struct QuoteCatalogue {
    @split-doc { css-all "article.quote" }
    quote_text {
        css ".text"
        text
        trim
        rm-prefix-suffix "\""
        assert "Quote must not be empty" { len-ge 5 }
    }
    likes {
        css ".likes"
        attr "data-count"
        to-int
        fallback 0
    }
    author_info { nested QuoteAuthor }
}

// KDL 2.0 Schema DSL (v2.1) — E-Commerce Product Page + Embedded JSON
json OfferPayload {
    sku str
    currency str
    in_stock bool from="availability.in_stock"
}

(item)struct ProductPage {
    @init {
        card { css "section.product-card" }
    }
    @pre-validate {
        assert "Expected product card container" { css "section.product-card" }
    }
    @check is-available {
        css ".stock-badge"
        to-bool
        fallback #false
    }
    title {
        @card
        css { "h1.product-title"; "h1" }
        text
        normalize-space
    }
    price_usd {
        @card
        css ".price-value"
        text
        re #"\$([0-9]+\.[0-9]{2})"#
        to-float
    }
    gallery_images {
        @card
        css-all "img.gallery-thumb"
        filter {
            has-attr "src"
            not { attr-contains "src" "placeholder" }
        }
        attr "src"
        unique
    }
    offer {
        @card
        css "script#offer-json"
        text
        jsonify OfferPayload path="data.offer"
    }
}

// KDL 2.0 Schema DSL (v2.1) — Key-Value Table Extraction
(table)struct HardwareSpecs {
    @table { css "table.specs-sheet" }
    @rows { css-all "tbody tr" }
    @match { css "th"; text; trim }
    @value { css "td"; text; trim }

    model_name {
        match { eq "Model" "Model Name" }
    }
    switch_type {
        match { starts "Switch" }
    }
    polling_hz {
        match { eq "Polling Rate" }
        re #"([0-9]+)\s*Hz"#
        to-int
    }
    weight_kg {
        match { eq "Weight" }
        re #"([0-9]+\.[0-9]+)\s*kg"#
        to-float
    }
    connectivity {
        match { eq "Connectivity" }
        split ", "
    }
}

// KDL 2.0 Schema DSL (v2.1) — HTML Dictionary & Flat List
(flat)struct DocLinks keep-order=#true {
    nav_urls { css-all "nav a.nav-link"; attr "href" }
    footer_urls { css-all "footer a.ext-link"; attr "href" }
}

(dict)struct PageMetaMap {
    @split-doc { css-all "head meta[name]" }
    @key { attr "name"; lower; trim }
    @value { attr "content"; trim }
}

// KDL 2.0 Schema DSL (v2.1) — Plain-Text (raw)struct Extraction
(raw)struct ReleaseLogEntries {
    @split-doc { split "\n" }
    version {
        re #"release=v([0-9]+\.[0-9]+\.[0-9]+)"#
    }
    channel {
        re #"channel=([a-z]+)"#
        upper
    }
    downloads {
        re #"downloads=([0-9]+)"#
        to-int
    }
    modules {
        re-all #"mod:([a-z0-9_-]+)"#
    }
}

// KDL 2.0 Schema DSL (v2.1) — Typed REST Client & GJSON Projectors
define API-BASE="https://api.example.com/v1"
define GET-REPO="curl -H 'Accept: application/json' '{{API-BASE}}/repos/{{owner:str}}/{{repo:str}}?include_stats={{include_stats:bool?}}&tags={{tags:str[]?|csv}}'"
define ARCHIVE-REPO="curl -X DELETE '{{API-BASE}}/repos/{{owner:str}}/{{repo:str}}'"

(dict)json LanguageBreakdown {
    @key str
    @value int
}

json RateLimitError {
    message str
    retry_after int from="meta.retry_after_seconds"
}

json ApiError {
    code str
    detail str from="error.detail"
}

json RepositorySummary {
    repo_id int from=#"meta.repo\.id"#
    full_name str
    owner_login str from="owner.login"
    topic_count int from="topics.#"
    topic_names (array)str from="topics.#.name"
    primary_topic str? from="topics.0.name" @omitempty
    languages LanguageBreakdown
    internal_trace str? @skip
}

(rest)struct RepositoryApi {
    @doc "Typed REST client for repository metadata and lifecycle operations"
    @request name="get-repository" response="RepositorySummary" GET-REPO
    @request name="archive-repository" response=#null ARCHIVE-REPO

    @error:not-found 404 ApiError code="REPO_NOT_FOUND"
    @error:rate-limited 429 RateLimitError "meta.retry_after_seconds"
    @error 400 ApiError "error.detail"
}
